(()=>{'use strict';const rows=[...document.querySelectorAll('[data-entry]')],picks=[...document.querySelectorAll('[data-choose]')],names=['Aurora','SplitText','BlurText','ScrollReveal','GlareHover','ChromaGrid'],notes=["用于给首屏增加低对比的环境层，先保证正文可读。", "只在重要短标题中强调阅读顺序，避免影响正文浏览。", "先让含义可读，再用轻微清晰度变化辅助入场。", "按阅读顺序显露内容，减少动态时保留完整正文。", "指针与焦点要有对应反馈；触摸端使用清楚的选中状态。", "先对齐图片裁切与留白，再安排色彩和指向反馈。"];let selected=-1;const $=s=>document.querySelector(s);function render(){rows.forEach((n,i)=>n.setAttribute('aria-pressed',String(i===selected)));picks.forEach((n,i)=>n.setAttribute('aria-pressed',String(i===selected)));$('#entry-selection').textContent=selected<0?'尚未选择条目。选择后只更新本地用途说明，不运行组件。':names[selected]+' · '+notes[selected];$('#read-entry').disabled=$('#clear-entry').disabled=selected<0}function choose(i,seek){selected=i;if(seek)study.seek(6.4);render()}picks.forEach((n,i)=>n.onclick=()=>choose(i,true));rows.forEach((n,i)=>n.onclick=()=>choose(i,false));$('#read-entry').onclick=e=>{if(selected>=0)study.show(names[selected]+' · 自写用途说明',notes[selected]+' 这里只查看用途，不代表该组件已安装或执行。',e.currentTarget)};$('#clear-entry').onclick=()=>{selected=-1;render();picks[0].focus()};addEventListener('study-reset',()=>{selected=-1;render()});addEventListener('study-change',()=>{const t=study.state().t;$('#folds').style.transform='translate('+Math.sin(t*.38)*34+'px,'+Math.sin(t*.27)*45+'px) rotate('+Math.sin(t*.18)*2+'deg)'});window.shelfStudy={state:()=>({selected,name:names[selected]||null,notes:selected<0?null:notes[selected],count:rows.length})};render()})();
